// This file personalises the ISCC Trust Seal shown beside the title of a certificate
// that proves inclusion. The seal template is a byte-verbatim copy of the iscc-brand
// kit's build/seal/iscc-trust-seal.template.svg (generated by its source/seal.py); never
// hand-edit it, copy a rebuilt one instead. Every character of the ring lettering has a
// fixed position in the template, so personalising it is string substitution of an id
// and a date of exactly the shapes the template lays out. The seal vouches for the
// evidence, not for the content, and the page keeps its "verifiable cache, not a trusted
// oracle" line.
package certificate

import (
	_ "embed"
	"html/template"
	"regexp"
	"strings"
	"time"
)

// sealTemplate is the brand kit's ISCC Trust Seal template, with {{ISCC_ID}} and {{DATE}}
// placeholders (each appearing in the lettering and in the aria-label).
//
//go:embed iscc-trust-seal.template.svg
var sealTemplate string

// sealIDPattern matches the only id shape the seal lays out: "ISCC:" and 16 base32
// characters, the canonical form of every ISCC-IDv1.
var sealIDPattern = regexp.MustCompile(`^ISCC:[A-Z2-7]{16}$`)

// trustSeal returns the ISCC Trust Seal for id, dated with the UTC day of at, as inline
// SVG. It returns empty for an id of any other shape, so a page never shows a seal whose
// lettering would not line up. The result is safe to inline: the template is a trusted
// brand asset and the substituted values contain only base32 letters, digits, a colon
// and hyphens.
func trustSeal(id string, at time.Time) template.HTML {
	if !sealIDPattern.MatchString(id) {
		return ""
	}
	r := strings.NewReplacer("{{ISCC_ID}}", id, "{{DATE}}", at.UTC().Format("2006-01-02"))
	return template.HTML(r.Replace(sealTemplate))
}
